        internal static Vector3[] Points(string model) => model!=null&&samples.TryGetValue(model, out var points) ? points : null;

        internal static float LowestY(Transform visual, Vector3[] points)
        {
            Matrix4x4 matrix = visual.localToWorldMatrix;
            Vector3 worldUp = new Vector3(matrix.m10, matrix.m11, matrix.m12);
            float lowest = float.PositiveInfinity;
            foreach (var point in points) lowest = Mathf.Min(lowest, Vector3.Dot(worldUp, point));
            return matrix.m13 + lowest;
        }

